/* ===== Media (custom AudioStyle/VideoStyle) ===== */
/* A media node with custom control children wraps a bare (control-less) media
   element; the element is the app-driven playback sink, so it stays hidden and
   only the custom control children are visible. Native media (no children)
   keep their own `controls` and are not wrapped. */
.pathland-media audio,
.pathland-media video { display: none; }

/* ===== Native controls (inherit Tailwind-derived preflight + tokens) ===== */
/* Every native form control shares the design-system surface: the Tailwind
   preflight supplies the font/color reset, these tokens supply the visual base.
   App-authored inline properties (WIDTH/HEIGHT/PADDING/COLOR/…) still win. */
.pathland-control,
.pathland-input {
  border-radius: var(--pl-input-radius);
  background-color: var(--pl-input-background);
  font-family: inherit;
  font-size: var(--pl-input-font-size);
  line-height: var(--pl-control-line-height);
  color: var(--pl-input-foreground);
  outline: var(--pl-control-border-width) solid var(--pl-input-border);
  outline-offset: calc(-1 * var(--pl-control-border-width));
  transition: outline-color var(--pl-control-transition-duration), box-shadow var(--pl-control-transition-duration);
  accent-color: var(--pl-control-accent);
  color-scheme: inherit;
}
.pathland-control {
  min-height: var(--pl-control-height);
  padding: var(--pl-control-padding-vertical) var(--pl-control-padding-horizontal);
}
.pathland-input {
  display: block;
  width: 100%;
  flex: 1 1 auto;
  min-width: 0;
  padding: var(--pl-input-padding-vertical) var(--pl-input-padding-horizontal);
}
.pathland-input::placeholder,
.pathland-control::placeholder { color: var(--pl-input-placeholder); }
.pathland-input:focus,
.pathland-control:focus {
  outline: var(--pl-input-focus-ring-width) solid var(--pl-input-focus);
  outline-offset: var(--pl-input-focus-ring-offset);
}
.pathland-control:disabled { opacity: var(--pl-opacity-disabled); }

/* PICKER: keep the native dropdown affordance; theme the field + options. */
.pathland-select { display: inline-block; cursor: pointer; }
.pathland-select option {
  background-color: var(--pl-input-background);
  color: var(--pl-input-foreground);
}

/* DATE_PICKER / COLOR_PICKER: the popup itself is UA-owned; the field surface,
   scheme, and picker highlights follow the design system. */
.pathland-date,
.pathland-color { display: inline-flex; align-items: center; }
.pathland-color { padding: var(--pl-control-padding-vertical); }
.pathland-color::-webkit-color-swatch-wrapper { padding: 0; }
.pathland-color::-webkit-color-swatch {
  border: 0;
  border-radius: calc(var(--pl-input-radius) - var(--pl-input-swatch-inset));
}

/* PROGRESS_VIEW: tokenized track/fill across engines. */
.pathland-progress {
  appearance: none;
  -webkit-appearance: none;
  display: block;
  width: 100%;
  height: var(--pl-progress-height);
  border: 0;
  border-radius: var(--pl-progress-radius);
  overflow: hidden;
  background-color: var(--pl-progress-track);
  color: var(--pl-progress-fill);
  accent-color: var(--pl-progress-fill);
}
.pathland-progress::-webkit-progress-bar {
  background-color: var(--pl-progress-track);
  border-radius: var(--pl-progress-radius);
}
.pathland-progress::-webkit-progress-value {
  background-color: var(--pl-progress-fill);
  border-radius: var(--pl-progress-radius);
}
.pathland-progress::-moz-progress-bar {
  background-color: var(--pl-progress-fill);
  border-radius: var(--pl-progress-radius);
}

/* VIDEO: native controls are UA shadow DOM (best-effort scheme/accent only);
   app-driven media (`.pathland-media` + custom controls) is fully themeable. */
.pathland-video,
.pathland-media {
  max-width: 100%;
  background-color: var(--pl-color-surface);
  color: var(--pl-color-text-primary);
  border-radius: var(--pl-control-radius);
  accent-color: var(--pl-control-accent);
  color-scheme: inherit;
}

/* ===== Stepper ===== */
.pathland-stepper { display: inline-flex; align-items: center; gap: var(--pl-stepper-gap); }
.pathland-stepper button { width: var(--pl-stepper-button-size); height: var(--pl-stepper-button-size); border-radius: var(--pl-stepper-radius); border: var(--pl-stepper-border-width) solid var(--pl-stepper-border); background: var(--pl-stepper-background); color: var(--pl-stepper-accent); }

/* ===== Progress / gauge / spinner ===== */
.pathland-spinner {
  width: var(--pl-spinner-size); height: var(--pl-spinner-size); border: var(--pl-spinner-border-width) solid var(--pl-progress-track);
  border-top-color: var(--pl-progress-fill); border-radius: var(--pl-radius-full);
  animation: pathland-spin var(--pl-spinner-duration) linear infinite;
}
@keyframes pathland-spin { to { transform: rotate(360deg); } }
.pathland-gauge { display: block; height: var(--pl-gauge-height); width: 100%; background: var(--pl-gauge-track); border-radius: var(--pl-gauge-radius); overflow: hidden; }
.pathland-gauge > div { height: 100%; background: var(--pl-gauge-fill); transition: width var(--pl-gauge-transition-duration); }

/* ===== Menu (popover) ===== */
.pathland-menu { position: relative; display: inline-block; }
.pathland-menu-items {
  display: none; position: absolute; min-width: var(--pl-menu-min-width); background: var(--pl-menu-background);
  color: var(--pl-menu-foreground); border: var(--pl-menu-border-width) solid var(--pl-menu-border); border-radius: var(--pl-menu-radius);
